        ans: "ઈ.સ. 1876 માં બનેલા 'ભારતીય નિધિ વ્યાપાર કાનૂન' મુજબ, જો કોઈ પણ નાગરિકને ખેતર ખેડતાં, કૂવો ખોદતાં કે રસ્તા બનાવતાં જમીનમાંથી અચાનક કોઈ પૌરાણિક કે ઐતિહાસિક મહત્વ ધરાવતી કિંમતી વસ્તુ (જેમ કે સિક્કા, મૂર્તિ, ઘરેણાં) મળી આવે, તો તેણે તરત જ પુરાતત્ત્વ ખાતાને તેની જાણ કરવી ફરજિયાત છે.",
        trick: "શોર્ટકટ ટ્રીક: 1876 નો કાયદો = જમીનમાંથી જૂની વસ્તુ મળે તો ખિસ્સામાં નહિ, પણ સરકારને જમા કરાવો."
