        ans: "• ખરીફ પાક: ચોમાસાની ઋતુમાં (જૂન-જુલાઈ થી ઓક્ટોબર-નવેમ્બર સુધી) લેવામાં આવતા પાકને 'ખરીફ પાક' કહે છે. દા.ત. ડાંગર, મકાઈ, જુવાર, બાજરી, કપાસ, મગફળી વગેરે.\n• રવિ પાક: શિયાળાની ઋતુમાં (ઓક્ટોબર-નવેમ્બર થી માર્ચ-એપ્રિલ સુધી) લેવામાં આવતા પાકને 'રવિ પાક' કહે છે. દા.ત. ઘઉં, ચણા, સરસવ, જવ વગેરે.",
        trick: "શોર્ટકટ ટ્રીક: ખરીફ = ચોમાસું (ખરાબ વરસાદમાં થાય તે). રવિ = શિયાળું (રવિ એટલે સૂર્ય, શિયાળામાં તડકો ગમે)."
