        q: "વ્યક્તિગત અને સામૂહિક સંદેશાવ્યવહાર એટલે શું?",
        ans: "• વ્યક્તિગત સંદેશાવ્યવહાર: જ્યારે માહિતીની આપ-લે માત્ર બે વ્યક્તિઓ વચ્ચે થતી હોય તેને વ્યક્તિગત સંદેશાવ્યવહાર કહે છે. દા.ત. ટેલિફોન, મોબાઈલ, ઈ-મેલ, ટપાલ.\n• સામૂહિક સંદેશાવ્યવહાર: જ્યારે કોઈ એક માહિતી એકસાથે લાખો લોકો (સમૂહ) સુધી પહોંચાડવાની હોય તેને સામૂહિક સંદેશાવ્યવહાર કહે છે. દા.ત. રેડિયો, ટેલિવિઝન (TV), વર્તમાનપત્રો અને ફિલ્મો.",
        trick: "શોર્ટકટ ટ્રીક: વ્યક્તિગત = 1 to 1 (પ્રાઇવેટ). સામૂહિક = 1 to Many (પબ્લિક)."
