        q_no: 12,
        type: "mcq",
        q: "ભારત સરકારે 'વાયુ પ્રદૂષણ નિયંત્રણ ધારો' કયા વર્ષમાં પસાર કર્યો?",
        options: ["(A) 1972", "(B) 1981", "(C) 1991", "(D) 2001"],
