        options: ["(A) 1 ઓક્ટોબર", "(B) 10 ડિસેમ્બર", "(C) 8 માર્ચ", "(D) 5 જૂન"],
        ans: "(A) 1 ઓક્ટોબર",
        trick: "શોર્ટકટ ટ્રીક: ઓક્ટોબરનો પહેલો દિવસ (1st October) ઘરમાં વડીલને પગે લાગવાનો (વૃદ્ધ દિન)."
